import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int p = scanner.nextInt();
        int k = scanner.nextInt();
        boolean[] visitedNodes = new boolean[p];
        int totalCycles = 0;
        for (int node = 0; node < p; node++) {
            if (!visitedNodes[node]) {
                totalCycles++;
                int current = node;
                while (!visitedNodes[current]) {
                    visitedNodes[current] = true;
                    current = (int) Math.fmod(current * k, p);
                }
            }
        }
        if (k == 0) {
            totalCycles = p;
        } else if (k == 1) {
            totalCycles = p + 1;
            long result = 1;
            long MOD = 1000000007;
            for (int i = 0; i < totalCycles - 1; i++) {
                result = (result * p) % MOD;
            }
            System.out.println(result);
        }
        scanner.close();
    }
}
